cd /tmp && cat > render.py <<'EOF'
import json, glob, collections, sys

res = collections.defaultdict(list)
for f in glob.glob('export/*.ndjson'):
    for line in open(f):
        line=line.strip()
        if line:
            r=json.loads(line)
            res[r['resourceType']].append(r)

def ext(r,name,default=None):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return default

def et(r): return ext(r,'event-time','')

pats = {p['id']:p for p in res['Patient']}
specs = {s['id']:s for s in res['Specimen']}
acc = {}
for b in res['Basic']:
    acc[ext(b,'accession')] = b

byp = collections.defaultdict(list)
for t,rs in res.items():
    if t in ('Patient',): continue
    for r in rs:
        s = r.get('subject',{}).get('reference') or r.get('patient',{}).get('reference') or r.get('for',{}).get('reference')
        if s: byp[s.split('/')[1]].append(r)

def fmt(r):
    t=r['resourceType']; i=r['id']; e=et(r)
    if t=='EpisodeOfCare':
        return f"[{e}] EpisodeOfCare {i}: start={r['period']['start']} {r['type'][0]['text']}"
    if t=='Condition':
        return f"[{e}] Condition {i}: {r['code']['text']} recorded={r.get('recordedDate')} recorder={r.get('recorder',{}).get('display')}"
    if t=='Observation':
        sp = r.get('specimen',{}).get('reference','')
        spid = sp.split('/')[-1]
        sr = specs.get(spid)
        slab = ''
        if sr:
            slab = f" spec={spid} label={ext(sr,'label-name')}/{ext(sr,'label-mrn')}/{ext(sr,'label-dob')} acc={sr.get('accessionIdentifier',{}).get('value')} collected={sr.get('collection',{}).get('collectedDateTime')} subj={sr.get('subject',{}).get('reference')}"
        accn = (r.get('identifier') or [{}])[0].get('value')
        a = acc.get(accn)
        alab = ''
        if a:
            alab = f" ACC[{a['id']}]={ext(a,'patient-name')}/{ext(a,'patient-mrn')}/{ext(a,'patient-dob')} recv={ext(a,'received')}"
        notes = ' | '.join(n.get('text','') for n in r.get('note',[]))
        return (f"[{e}] Observation {i}: {r['code']['text']} status={r['status']} eff={r.get('effectiveDateTime')} issued={r.get('issued')} "
                f"val={r.get('valueString')} accn={accn}{slab}{alab}" + (f" NOTE: {notes}" if notes else ""))
    if t=='Specimen':
        return f"[{e}] Specimen {i}: acc={r.get('accessionIdentifier',{}).get('value')} coll={r.get('collection',{}).get('collectedDateTime')} by {r.get('collection',{}).get('collector',{}).get('display')} label={ext(r,'label-name')}/{ext(r,'label-mrn')}/{ext(r,'label-dob')}"
    if t=='MedicationAdministration':
        notes = ' | '.join(n.get('text','') for n in r.get('note',[]))
        return f"[{e}] MedAdmin {i}: status={r['status']} eff={r.get('effectiveDateTime')} med={r.get('medicationCodeableConcept',{}).get('text')} dose={r.get('dosage',{}).get('text')} perf={[p.get('actor',{}).get('display') for p in r.get('performer',[])]}" + (f" NOTE: {notes}" if notes else "")
    if t=='MedicationDispense':
        notes = ' | '.join(n.get('text','') for n in r.get('note',[]))
